<?php
include 'includes/init.php';require_role(['Admin','Manager']);
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?$_GET['from']:date('Y-01-01');$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?$_GET['to']:date('Y-m-d');
$stmt=$conn->prepare("SELECT a.code,a.name,a.type,a.normal_balance,COALESCE(SUM(CASE WHEN je.entry_date BETWEEN ? AND ? AND je.status='Posted' THEN jl.debit-jl.credit ELSE 0 END),0) raw_period,COALESCE(SUM(CASE WHEN je.entry_date<=? AND je.status='Posted' THEN jl.debit-jl.credit ELSE 0 END),0) raw_to_date FROM accounts a LEFT JOIN journal_lines jl ON jl.account_id=a.id LEFT JOIN journal_entries je ON je.id=jl.journal_entry_id GROUP BY a.id ORDER BY a.code");$stmt->execute([$from,$to,$to]);$accounts=$stmt->fetchAll();$groups=['Asset'=>[],'Liability'=>[],'Equity'=>[],'Revenue'=>[],'Expense'=>[]];foreach($accounts as $a){$a['period']=$a['normal_balance']==='Credit'?-$a['raw_period']:$a['raw_period'];$a['to_date']=$a['normal_balance']==='Credit'?-$a['raw_to_date']:$a['raw_to_date'];$groups[$a['type']][]=$a;}$sum=function($rows,$key){return array_sum(array_column($rows,$key));};$revenue=$sum($groups['Revenue'],'period');$expense=$sum($groups['Expense'],'period');$profit=$revenue-$expense;$assets=$sum($groups['Asset'],'to_date');$liabilities=$sum($groups['Liability'],'to_date');$equity=$sum($groups['Equity'],'to_date')+$profit;$cashStmt=$conn->prepare("SELECT je.entry_date,je.description,SUM(jl.debit-jl.credit) movement FROM journal_lines jl JOIN journal_entries je ON je.id=jl.journal_entry_id JOIN accounts a ON a.id=jl.account_id WHERE a.code='1000' AND je.status='Posted' AND je.entry_date BETWEEN ? AND ? GROUP BY je.id ORDER BY je.entry_date DESC,je.id DESC");$cashStmt->execute([$from,$to]);$cashRows=$cashStmt->fetchAll();$cashNet=array_sum(array_column($cashRows,'movement'));
?>
<div class="container-fluid"><div class="d-flex justify-content-between mb-4"><h3>Financial Statements</h3><button onclick="print()" class="btn btn-outline-primary"><i class="bx bx-printer"></i> Print / PDF</button></div><div class="card mb-4"><div class="card-body"><form class="row g-3 align-items-end"><div class="col-md-5"><label class="form-label">From</label><input type="date" name="from" value="<?=escape($from)?>" class="form-control"></div><div class="col-md-5"><label class="form-label">To</label><input type="date" name="to" value="<?=escape($to)?>" class="form-control"></div><div class="col-md-2"><button class="btn btn-primary w-100">Apply</button></div></form></div></div>
<div class="row"><div class="col-lg-6 mb-4"><div class="card h-100"><div class="card-header"><h5>Profit & Loss</h5><small><?=escape($from)?> to <?=escape($to)?></small></div><div class="card-body"><?php foreach(['Revenue','Expense'] as $type):?><h6 class="text-uppercase mt-3"><?=$type?></h6><?php foreach($groups[$type] as $a):if(abs($a['period'])<.005)continue;?><div class="d-flex justify-content-between border-bottom py-2"><span><?=escape($a['code'].' '.$a['name'])?></span><span><?=money($a['period'])?></span></div><?php endforeach;?><div class="d-flex justify-content-between fw-bold py-2"><span>Total <?=$type?></span><span><?=money($type==='Revenue'?$revenue:$expense)?></span></div><?php endforeach;?><div class="alert <?= $profit>=0?'alert-success':'alert-danger'?> d-flex justify-content-between mt-3"><strong>Net Profit</strong><strong><?=money($profit)?></strong></div></div></div></div>
<div class="col-lg-6 mb-4"><div class="card h-100"><div class="card-header"><h5>Balance Sheet</h5><small>As at <?=escape($to)?></small></div><div class="card-body"><?php foreach(['Asset','Liability','Equity'] as $type):?><h6 class="text-uppercase mt-3"><?=$type?></h6><?php foreach($groups[$type] as $a):if(abs($a['to_date'])<.005)continue;?><div class="d-flex justify-content-between border-bottom py-2"><span><?=escape($a['code'].' '.$a['name'])?></span><span><?=money($a['to_date'])?></span></div><?php endforeach;?><div class="d-flex justify-content-between fw-bold py-2"><span>Total <?=$type?></span><span><?=money($type==='Asset'?$assets:($type==='Liability'?$liabilities:$equity))?></span></div><?php endforeach;?><div class="alert alert-info d-flex justify-content-between mt-3"><strong>Liabilities + Equity</strong><strong><?=money($liabilities+$equity)?></strong></div></div></div></div></div><div class="card mb-4"><div class="card-header d-flex justify-content-between"><h5>Cash Flow Activity</h5><strong><?=money($cashNet)?></strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Description</th><th class="text-end">Movement</th></tr></thead><tbody><?php foreach($cashRows as $r):?><tr><td><?=escape($r['entry_date'])?></td><td><?=escape($r['description'])?></td><td class="text-end <?= $r['movement']>=0?'text-success':'text-danger'?>"><?=money($r['movement'])?></td></tr><?php endforeach;?><?php if(!$cashRows):?><tr><td colspan="3" class="text-center py-4">No cash movements.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php include 'includes/footer.php';?>
